SELECT /* LGVPAY00025.retrieveCalSetEmpList */ tpe.payment_yyyymm AS pay_month , em.employee_number AS employee_no , em.full_name_english AS employee_name , em.full_name_local AS employee_name_local , em.organization_id , um.default_org_id , em.org_name_local AS organization_name , em.person_type , em.assignment_category AS employment_category_code , em.status , em.grade AS grade_code , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') as date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') as date_retire , (SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS grade_title , em.grade_type AS emp_category_name , em.attribute10 AS shift_type_code ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , em.supervisor , (select ema.full_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_name , (select ema.org_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_org_name , (select om.parent_org_name from org_master om where om.organization_id = em.organization_id) as section , um.employee_mobile_phone_no as mobile_phone , tpe.user_email_addr as email_outside , tpe.remark_text as remark , tpe.payroll_calculation_exec_id as payroll_calculation_exec_id , tpe.slip_creation_flag as create_payslip_flag , tpe.error_message_content as create_payslip_error , tpe.transfer_flag as send_flag , tpe.mail_send_error_content as send_error FROM tb_pay_slip_send_n tpe , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE em.employee_number = tpe.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code AND tpe.payment_yyyymm = #{payMonth}
AND tpe.employee_no = #{employeeNo}
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
AND tpe.payroll_calculation_exec_id = #{payrollCalculationExecId}
AND tpe.transfer_flag = #{sendFlag}
AND tpe.slip_creation_flag = #{createFlag}
ORDER BY em.employee_number asc

SELECT /* LGVPAY00025.createDirectCSVDownloadData */ employee_no , employee_name_local , employee_name , email_outside , remark , organization_name , person_type , status , grade_code , grade_title , emp_category_name , date_hire_subsidiary , date_retire , supervisor , supervisor_name , supervisor_org_name , mobile_phone , shift_type_name , payroll_calculation_exec_id , send_error FROM ( SELECT '1' gubun , 'Employee No' AS EMPLOYEE_NO , 'Employee Name' AS EMPLOYEE_NAME_LOCAL , 'Employee Eng Name' AS EMPLOYEE_NAME , 'e-Mail' AS EMAIL_OUTSIDE , 'Remark' AS REMARK , 'Organization Name' AS ORGANIZATION_NAME , 'Type' AS PERSON_TYPE , 'Status' AS STATUS , 'Grade' AS GRADE_CODE , 'Title' AS GRADE_TITLE , 'Emp. Category' AS EMP_CATEGORY_NAME , 'Hire Date' AS DATE_HIRE_SUBSIDIARY , 'Resignation Date' AS DATE_RETIRE , 'Supervisor' AS SUPERVISOR , 'Supervisor' AS SUPERVISOR_NAME , 'Supervisor' AS SUPERVISOR_ORG_NAME , 'Mobile Phone No.' AS MOBILE_PHONE , 'Work Type' AS SHIFT_TYPE_NAME , 'Calculation Set' AS PAYROLL_CALCULATION_EXEC_ID , 'Error' AS SEND_ERROR FROM DUAL UNION ALL SELECT '2' gubun , em.employee_number AS employee_no , em.full_name_english AS employee_name , em.full_name_local AS employee_name_local , tpe.user_email_addr AS email_outside , tpe.remark_text AS remark , em.org_name_local AS organization_name , em.person_type AS person_type , em.status AS status , em.grade AS grade_code , (SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS grade_title , em.grade_type AS emp_category_name , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') AS date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') AS date_retire , em.supervisor AS supervisor , (select ema.full_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_name , (select ema.org_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_org_name , um.employee_mobile_phone_no as mobile_phone ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , to_char(tpe.payroll_calculation_exec_id) AS payroll_calculation_exec_id , tpe.mail_send_error_content AS send_error FROM tb_pay_slip_send_n tpe , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE em.employee_number = tpe.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code AND tpe.payment_yyyymm = #{payMonth}
AND tpe.employee_no = #{employeeNo}
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
AND tpe.payroll_calculation_exec_id = #{payrollCalculationExecId}
AND tpe.mail_send_error_content is not null
) ORDER BY employee_no asc

