INSERT INTO /* LGVPAY00025.createExcelDownloadData */ XXLGE_EXPORT_INFO (SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8 , ATTRIBUTE9, ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15 , ATTRIBUTE16, ATTRIBUTE17, ATTRIBUTE18, ATTRIBUTE19, ATTRIBUTE20) SELECT AA.* FROM ( SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 1 AS ORDER_BY , 'KO16KSC5601' , 'Employee No' AS EMPLOYEE_NO , 'Employee Name' AS EMPLOYEE_NAME_LOCAL , 'Employee Eng Name' AS EMPLOYEE_NAME , 'e-Mail' AS EMAIL_OUTSIDE , 'Remark' AS REMARK , 'Organization Name' AS ORGANIZATION_NAME , 'Type' AS PERSON_TYPE , 'Status' AS STATUS , 'Grade' AS GRADE_CODE , 'Title' AS GRADE_TITLE , 'Emp. Category' AS EMP_CATEGORY_NAME , 'Hire Date' AS DATE_HIRE_SUBSIDIARY , 'Resignation Date' AS DATE_RETIRE , 'Supervisor' AS SUPERVISOR , 'Supervisor' AS SUPERVISOR_NAME , 'Supervisor' AS SUPERVISOR_ORG_NAME , 'Mobile Phone No.' AS MOBILE_PHONE , 'Work Type' AS SHIFT_TYPE_NAME , 'Calculation Set' AS PAYROLL_CALCULATION_EXEC_ID , 'Error' AS SEND_ERROR FROM DUAL UNION ALL SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 2 AS ORDER_BY , 'KO16KSC5601' , em.employee_number AS employee_no , em.full_name_english AS employee_name , em.full_name_local AS employee_name_local , tpe.user_email_addr AS email_outside , tpe.remark_text AS remark , em.org_name_local AS organization_name , em.person_type AS person_type , em.status AS status , em.grade AS grade_code , (SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS grade_title , em.grade_type AS emp_category_name , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') AS date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') AS date_retire , em.supervisor AS supervisor , (select ema.full_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_name , (select ema.org_name_local from emp_master ema where em.supervisor = ema.employee_number) as supervisor_org_name , um.employee_mobile_phone_no as mobile_phone ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , to_char(tpe.payroll_calculation_exec_id) AS payroll_calculation_exec_id , tpe.mail_send_error_content AS send_error FROM tb_pay_slip_send_n tpe , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE em.employee_number = tpe.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code AND tpe.payment_yyyymm = #{payMonth}
AND tpe.employee_no = #{employeeNo}
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
AND tpe.payroll_calculation_exec_id = #{payrollCalculationExecId}
AND tpe.mail_send_error_content is not null
ORDER BY ORDER_BY, EMPLOYEE_NO asc ) AA ORDER BY ORDER_BY, AA.EMPLOYEE_NO asc

